package main

import (
	"bufio"
	"fmt"
	"os"
)

type Fibonacci struct {
	mod               int64
	calculatedNumbers map[int64]int64
}

func NewFibonacci(mod int64) *Fibonacci {
	calculatedNumbers := make(map[int64]int64)
	calculatedNumbers[0] = 1
	calculatedNumbers[1] = 1
	return &Fibonacci{
		mod:               mod,
		calculatedNumbers: calculatedNumbers,
	}
}

func (f *Fibonacci) fib(n int64) int64 {
	if val, ok := f.calculatedNumbers[n]; ok {
		return val
	}
	k := n / 2
	var res int64
	if n%2 == 0 {
		res = (f.fib(k)*f.fib(k) + f.fib(k-1)*f.fib(k-1)) % f.mod
	} else {
		res = (f.fib(k)*f.fib(k+1) + f.fib(k-1)*f.fib(k)) % f.mod
	}
	f.calculatedNumbers[n] = res
	return res
}

type Exponentation struct{}

func (e Exponentation) calc(a, b, m int64) int64 {
	if b == 0 {
		return 1
	}
	if b == 1 {
		return a % m
	}
	if b%2 == 0 {
		return e.calc(a*a%m, b/2, m)
	}
	return a * e.calc(a*a%m, (b-1)/2, m) % m
}

type Solver struct {
	n, k, l, MOD int64
}

func (s *Solver) read(in *InputReader) {
	s.n = in.nextLong()
	s.k = in.nextLong()
	s.l = in.nextLong()
	s.MOD = in.nextLong()
}

func (s *Solver) solve(in *InputReader, out *bufio.Writer) {
	s.read(in)
	if s.l != 64 && (int64(1)<<s.l)-1 < s.k {
		fmt.Fprintln(out, 0)
		return
	}

	zeroPos := NewFibonacci(s.MOD).fib(s.n + 1)
	onePos := Exponentation{}.calc(2, s.n, s.MOD) - zeroPos
	for onePos < 0 {
		onePos += s.MOD
	}

	res := int64(1)
	for i := int64(0); i < s.l; i++ {
		if (s.k & (int64(1) << i)) != 0 {
			res *= onePos
		} else {
			res *= zeroPos
		}
		res %= s.MOD
	}
	fmt.Fprintln(out, res%s.MOD)
}

